s=s.replace('<div class="mode">','''<div class="setup"><label for="circuit">GRAND PRIX CIRCUIT</label><select id="circuit"><option value="monza">Monza · Italy</option><option value="silverstone">Silverstone · Great Britain</option><option value="monaco">Monaco · Monte Carlo</option></select><label for="steering">STEERING RESPONSE <output id="steerValue">1.4×</output></label><input id="steering" type="range" min="0.7" max="1.8" step="0.1" value="1.4"><small>Tight turning · tune for hairpins</small></div><div class="mode">''')
